function maximumAlternatingSubarraySum(nums) {
  let plus = nums[0];
  let minus = -Infinity;
  let best = nums[0];

  for (let i = 1; i < nums.length; i++) {
    const num = nums[i];
    const nextPlus = Math.max(minus, 0) + num;
    const nextMinus = plus - num;
    plus = nextPlus;
    minus = nextMinus;
    best = Math.max(best, plus, minus);
  }
  return best;
}

